SELECT CASE WHEN credit_limit >= 17100 THEN 'high' WHEN credit_limit >= 6100 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, segment, MIN(signup_date) AS min_signup_date, ROUND(AVG(credit_limit), 2) AS avg_credit_limit FROM customers WHERE country = 'TH' OR email LIKE '%@outlook.com' GROUP BY credit_limit_bucket, segment HAVING ROUND(AVG(credit_limit), 2) >= 42 ORDER BY min_signup_date;
